// Spectrum analyzer window (bsc lan analyzer) — the detached surface opened by
// `bsc lan analyzer open`. Top half the live 2.4 GHz spectrum, bottom half what
// the assistant can say about it.
//
// WHY A SEPARATE WINDOW. It survives the main surface being wedged, which is
// also why the window is built by the app's Rust side rather than by this web
// view — an escape hatch routed through the thing it escapes is not one.
//
// THE BINS ARE PEAKS, NOT AVERAGES, and the axis labels say so. The sensor
// aggregates ~666 sweeps/sec down to one record per channel per window and
// keeps the per-bin MAXIMUM, because a brief microwave burst is exactly what
// this tier exists to catch and averaging it against quiet sweeps is how it
// hides. Rendering it as a mean would undo that at the last step.
//
// WHERE THE DATA COMES FROM, and what does NOT come with it. The app's Rust
// half subscribes to the sensor's sealed UDP stream, verifies the Ed25519
// signature, decrypts, and decodes; this view receives already-authenticated
// records over a Tauri event and holds NO key of any kind. A webview cannot
// bind a UDP socket anyway, but even if it could, the group key is the
// confidentiality half of the whole stream and does not belong in a surface
// that renders remote-influenced content.
//
// STALE IS NOT FRESH AND NEITHER IS SILENT. A display that simply stops
// updating looks exactly like a quiet band. The three liveness states the
// subscription reports are rendered as three different things, and a dead
// sensor never leaves its last sweep on screen looking current.
import { useEffect, useMemo, useState } from "react";
import { listen } from "@tauri-apps/api/event";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";

export type SpectrumBins = {
  freqMhz: number;
  sweeps: number;
  noiseDbm: number;
  peakMagnitude: number;
  peakBin: number;
  binMax: number[];
  /** Milliseconds since the subscription started. Absent on a fixture. */
  receivedAtMs?: number;
};

/** What the subscription can say about whether the sensor is still there. */
export type LivenessState = "never-heard" | "healthy" | "late" | "silent";

export type Liveness = {
  state: LivenessState;
  sinceMs: number;
  overdueByMs: number;
};

/** Before anything at all has arrived — NOT a healthy stream. */
export const NEVER_HEARD: Liveness = { state: "never-heard", sinceMs: 0, overdueByMs: 0 };

/** Centre frequency of one FFT bin, for the axis. HT20 spans 20 MHz over 56 bins. */
export function binFrequencyMhz(centreMhz: number, bin: number, bins: number): number {
  const span = 20;
  return centreMhz - span / 2 + (span * (bin + 0.5)) / bins;
}

/** A bin's height as a fraction of the strongest bin present. */
export function binHeight(value: number, peak: number): number {
  if (peak <= 0) return 0;
  return Math.max(0, Math.min(1, value / peak));
}

/**
 * Fold one arriving record into the set on screen, keyed by centre frequency.
 *
 * KEYED, NOT LATEST. The sensor emits one record per channel per window, so a
 * radio sweeping two channels alternates between them. A single `latest` would
 * make the display flicker between the two and show neither for long enough to
 * read. Ordered by frequency so a channel does not jump position as it updates.
 */
export function foldChannel(prev: SpectrumBins[], next: SpectrumBins): SpectrumBins[] {
  const rest = prev.filter((c) => c.freqMhz !== next.freqMhz);
  return [...rest, next].sort((a, b) => a.freqMhz - b.freqMhz);
}

/**
 * Whether what is on screen may be presented as the air RIGHT NOW.
 *
 * Only `healthy` may. `late` and `silent` still render the last sweep — it is
 * the most recent truth there is — but marked, because the alternative is a
 * chart that quietly ages into a lie.
 */
export function isCurrent(l: Liveness): boolean {
  return l.state === "healthy";
}

/** Human-readable age, for a label rather than a calculation. */
export function ageLabel(ms: number): string {
  if (ms < 1000) return `${ms}ms`;
  const s = Math.floor(ms / 1000);
  if (s < 120) return `${s}s`;
  return `${Math.floor(s / 60)}m`;
}

/**
 * Subscribe to the app's LAN stream. Returns what has arrived and what the
 * subscription can say about the sensor's liveness.
 *
 * The liveness event carries the CURRENT verdict rather than only transitions,
 * so a window opened long after the last change still learns the state — "no
 * liveness yet" must not render the same as "healthy".
 */
export function useLanSpectrum(): { channels: SpectrumBins[]; liveness: Liveness } {
  const [channels, setChannels] = useState<SpectrumBins[]>([]);
  const [liveness, setLiveness] = useState<Liveness>(NEVER_HEARD);

  useEffect(() => {
    let disposed = false;
    const spectrum = listen<SpectrumBins>("lan://spectrum", (e) => {
      if (!disposed) setChannels((prev) => foldChannel(prev, e.payload));
    });
    const live = listen<Liveness>("lan://liveness", (e) => {
      if (!disposed) setLiveness(e.payload);
    });
    return () => {
      disposed = true;
      void spectrum.then((un) => un());
      void live.then((un) => un());
    };
  }, []);

  return { channels, liveness };
}

/**
 * What an empty panel should say, given whether the sensor is being heard.
 *
 * THE TWO CASES LOOK IDENTICAL AND ARE NOT THE SAME PROBLEM. A subscriber that
 * hears nothing has a network, key or sensor fault. A subscriber that hears the
 * sensor perfectly and receives no SPECTRUM has a radio fault — the sensor is
 * alive, attesting, and producing no FFT samples. Measured once, at length: an
 * hour of establishing from outside what this line says in six words.
 */
export function emptyStateDiagnosis(l: Liveness): string {
  switch (l.state) {
    case "never-heard":
      return "Nothing has been heard from the sensor at all — check the address and the keys.";
    case "healthy":
      return `The sensor IS heard (${ageLabel(l.sinceMs)} ago) but is sending no spectrum — its radio is producing nothing.`;
    case "late":
      return `The sensor is late by ${ageLabel(l.overdueByMs)} and has sent no spectrum.`;
    case "silent":
      return `The sensor has been silent for ${ageLabel(l.sinceMs)} — treat the stream as gone.`;
  }
}

function ChannelChart({ data, current }: { data: SpectrumBins; current: boolean }) {
  const peak = useMemo(
    () => data.binMax.reduce((m, v) => Math.max(m, v), 0),
    [data.binMax],
  );

  return (
    <Stack gap={6} style={{ padding: 12, opacity: current ? 1 : 0.55 }}>
      <Text as="div" mono>
        {data.freqMhz} MHz · {data.sweeps} sweeps · noise {data.noiseDbm} dBm · peak{" "}
        {data.peakMagnitude} at bin {data.peakBin}
      </Text>
      <Box
        style={{
          display: "flex",
          alignItems: "flex-end",
          gap: 1,
          flex: 1,
          minHeight: 140,
          borderBottom: "1px solid var(--border)",
        }}
      >
        {data.binMax.map((v, i) => (
          <Box
            key={i}
            title={`${binFrequencyMhz(data.freqMhz, i, data.binMax.length).toFixed(1)} MHz — peak ${v}`}
            style={{
              flex: 1,
              height: `${binHeight(v, peak) * 100}%`,
              background: i === data.peakBin ? "var(--accent)" : "var(--fg-dim)",
              minHeight: 1,
            }}
          />
        ))}
      </Box>
      <Text as="div" mono tone="dim" style={{ fontSize: 11 }}>
        per-bin PEAK across the window (not a mean) · {data.binMax.length} bins over 20 MHz
      </Text>
    </Stack>
  );
}

function Spectrum({ channels, liveness }: { channels: SpectrumBins[]; liveness: Liveness }) {
  if (channels.length === 0) {
    // Never render an empty chart as a quiet band: no data and a clear channel
    // look identical on a spectrum display, and only one of them is good news.
    //
    // AND SAY WHETHER THE SENSOR IS HEARD, which is the difference between two
    // completely different problems. MEASURED 2026-09-04: this panel showed
    // "no spectrum received yet" for an hour while the sensor was perfectly
    // healthy and delivering snapshots — its RADIO had wedged, producing zero
    // FFT samples. The screen said the same thing it would have said for a
    // wrong key, a dead sensor or an unplugged switch, and an hour went into
    // establishing from the outside what this line could have said outright.
    return (
      <Box style={{ padding: 24 }}>
        <Text as="div" mono tone="dim">
          No spectrum received yet — this is NOT a quiet band.
        </Text>
        <Text as="div" mono style={{ marginTop: 10 }}>
          {emptyStateDiagnosis(liveness)}
        </Text>
        <Text as="div" mono tone="dim" style={{ marginTop: 6, fontSize: 12 }}>
          The sensor emits one aggregated record per channel per window. If nothing
          arrives, check the multicast group and the keys before concluding the air is clear.
        </Text>
      </Box>
    );
  }

  const current = isCurrent(liveness);
  return (
    <Stack style={{ height: "100%", overflow: "auto" }}>
      {!current && (
        <Box style={{ padding: "8px 12px", borderBottom: "1px solid var(--border)" }}>
          <Text as="div" mono tone="dim">
            {liveness.state === "silent"
              ? `SENSOR SILENT for ${ageLabel(liveness.sinceMs)} — this is the LAST sweep, not the air now.`
              : `SENSOR LATE by ${ageLabel(liveness.overdueByMs)} — this is the LAST sweep, not the air now.`}
          </Text>
        </Box>
      )}
      {channels.map((c) => (
        <ChannelChart key={c.freqMhz} data={c} current={current} />
      ))}
    </Stack>
  );
}

function Assistant({ notes }: { notes: string[] }) {
  return (
    <Stack gap={6} style={{ padding: 16, overflow: "auto", height: "100%" }}>
      <Text as="div" mono tone="dim" style={{ fontSize: 11 }}>
        ASSISTANT
      </Text>
      {notes.length === 0 ? (
        <Text as="div" mono tone="dim">
          Nothing to report yet.
        </Text>
      ) : (
        notes.map((n, i) => (
          <Text as="div" mono key={i} style={{ fontSize: 12 }}>
            {n}
          </Text>
        ))
      )}
    </Stack>
  );
}

/**
 * The analyzer window: spectrum above, assistant below.
 *
 * Presentational on purpose — it takes what to draw rather than fetching it, so
 * every state it can be in (never heard, one channel, two channels, a silent
 * sensor holding a stale sweep) is reachable from a test without a socket.
 * [`LiveSpectrumAnalyzer`] is the half that subscribes.
 */
export function SpectrumAnalyzer({
  channels = [],
  liveness = NEVER_HEARD,
  notes = [],
}: {
  channels?: SpectrumBins[];
  liveness?: Liveness;
  notes?: string[];
}) {
  return (
    <Stack style={{ height: "100%" }}>
      <Box style={{ flex: "1 1 50%", minHeight: 0, borderBottom: "1px solid var(--border)" }}>
        <Spectrum channels={channels} liveness={liveness} />
      </Box>
      <Box style={{ flex: "1 1 50%", minHeight: 0 }}>
        <Assistant notes={notes} />
      </Box>
    </Stack>
  );
}

/** The analyzer, wired to the live stream. What the detached window renders. */
export function LiveSpectrumAnalyzer() {
  const { channels, liveness } = useLanSpectrum();
  return <SpectrumAnalyzer channels={channels} liveness={liveness} />;
}
